# Level 1

def calc_organizations_name(display_name):
    """
    Human-readable calculated display alias for the Organizations row.
    
    Formula: ={{DisplayName}}
    """
    return display_name

def calc_organizations_ai_fails_for_lack_of_captured_knowledge(failed_ai_initiative_count, owned_procedure_count):
    """
    TRUE for an organization with a failed AI initiative that has captured no procedures.
    
    Formula: =AND({{FailedAiInitiativeCount}} > 0, {{OwnedProcedureCount}} = 0)
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_cmp(failed_ai_initiative_count, '>', 0)), _erb.erb_bool3(_erb.erb_eq(owned_procedure_count, 0)))

def calc_organizations_is_hollowed_out_firm(product_delivery_function_count, provider_held_delivery_method_count):
    """
    TRUE when every function that delivers the organization's own products depends on method knowledge a provider holds.
    
    Formula: =AND({{ProductDeliveryFunctionCount}} > 0, {{ProviderHeldDeliveryMethodCount}} = {{ProductDeliveryFunctionCount}})
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_cmp(product_delivery_function_count, '>', 0)), _erb.erb_bool3(_erb.erb_eq(provider_held_delivery_method_count, product_delivery_function_count)))

def calc_organizations_has_knowledge_findings_without_knowledge_staff(audit_finding_count, filled_knowledge_position_count):
    """
    TRUE when audits found knowledge shortfalls and the organization employs no knowledge engineer, information architect or ontologist to address them.
    
    Formula: =AND({{AuditFindingCount}} > 0, {{FilledKnowledgePositionCount}} = 0)
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_cmp(audit_finding_count, '>', 0)), _erb.erb_bool3(_erb.erb_eq(filled_knowledge_position_count, 0)))

def calc_organizations_retained_departed_know_how_percent(departed_holder_know_how_count, lost_departed_know_how_count):
    """
    Share of departed carriers' know-how the organization kept.
    
    Formula: =IF({{DepartedHolderKnowHowCount}} = 0, 100, ROUND(100 * ({{DepartedHolderKnowHowCount}} - {{LostDepartedKnowHowCount}}) / {{DepartedHolderKnowHowCount}}, 0))
    """
    return (100 if _erb.erb_bool3(_erb.erb_eq(departed_holder_know_how_count, 0)) else _erb.erb_round(_erb.erb_div(_erb.erb_mul(100, _erb.erb_sub(departed_holder_know_how_count, lost_departed_know_how_count)), departed_holder_know_how_count), 0))

def calc_organizations_treats_knowledge_work_as_unvalued(documentation_entry_count, transfer_given_count, unallocated_documentation_count, unallocated_transfer_count):
    """
    TRUE when most documentation and knowledge transfer happens outside the time the organization allots.
    
    Formula: =AND({{DocumentationEntryCount}} + {{TransferGivenCount}} > 0, 2 * ({{UnallocatedDocumentationCount}} + {{UnallocatedTransferCount}}) > {{DocumentationEntryCount}} + {{TransferGivenCount}})
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_cmp(_erb.erb_add(documentation_entry_count, transfer_given_count), '>', 0)), _erb.erb_bool3(_erb.erb_cmp(_erb.erb_mul(2, _erb.erb_add(unallocated_documentation_count, unallocated_transfer_count)), '>', _erb.erb_add(documentation_entry_count, transfer_given_count))))

def calc_organizations_holds_know_how_in_people_plants_and_systems(person_carried_know_how_count, facility_carried_know_how_count, system_carried_know_how_count):
    """
    TRUE when the organization's how-to-build knowledge is carried at once by people, plants and systems.
    
    Formula: =AND({{PersonCarriedKnowHowCount}} > 0, {{FacilityCarriedKnowHowCount}} > 0, {{SystemCarriedKnowHowCount}} > 0)
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_cmp(person_carried_know_how_count, '>', 0)), _erb.erb_bool3(_erb.erb_cmp(facility_carried_know_how_count, '>', 0)), _erb.erb_bool3(_erb.erb_cmp(system_carried_know_how_count, '>', 0)))

def calc_organizations_eroded_in_stages(staged_decline_count):
    """
    TRUE when facility investment, then engineer training, then how-to-make upkeep declined in sequence.
    
    Formula: ={{StagedDeclineCount}} >= 2
    """
    return _erb.erb_cmp(staged_decline_count, '>=', 2)

# Level 2

def calc_organizations_memory_leaves_with_staff(departed_holder_know_how_count, retained_departed_know_how_percent):
    """
    TRUE when some know-how of people who left was not retained.
    
    Formula: =AND({{DepartedHolderKnowHowCount}} > 0, {{RetainedDepartedKnowHowPercent}} < 100)
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_cmp(departed_holder_know_how_count, '>', 0)), _erb.erb_bool3(_erb.erb_cmp(retained_departed_know_how_percent, '<', 100)))


