    return _erb.erb_or(_erb.erb_bool3(_erb.erb_cmp(deviated_run_count, '>=', 2)), _erb.erb_bool3(_erb.erb_and(_erb.erb_bool3(_erb.erb_cmp(deviated_run_count, '>', 0)), _erb.erb_bool3(_erb.erb_cmp(open_outdated_flag_count, '>', 0)))))

