# =============================================================================
# RESOURCES
# Documents, datasets, APIs, templates, images, manuals, and operational records referenced by procedures. Maps to dcat:Resource.
# =============================================================================

# Level 1

def calc_resources_name(title):
    """
    Human-readable calculated display alias for the Resources row.
    
    Formula: ={{Title}}
    """
    return title

def calc_resources_is_approved_source(approval_status):
    """
    TRUE when this resource is an approved source.
    
    Formula: ={{ApprovalStatus}} = "Approved" 
    """
    return _erb.erb_eq(_erb.erb_nullif(approval_status), 'Approved')

def calc_resources_is_stale_extraction(extracted_from_resource, source_modified_at, modified_at):
    """
    TRUE when the source a resource was extracted from changed after the extraction was last updated.
    
    Formula: =AND({{ExtractedFromResource}} <> "", {{SourceModifiedAt}} > {{ModifiedAt}})
    """
    return _erb.erb_and(_erb.erb_bool3((not (extracted_from_resource is None or extracted_from_resource == ""))), _erb.erb_bool3(_erb.erb_cmp(source_modified_at, '>', _erb.erb_nullif(modified_at))))

def calc_resources_is_unused_resource(referencing_step_count, referencing_version_count):
    """
    TRUE when no procedure or step uses the resource.
    
    Formula: =AND({{ReferencingStepCount}} = 0, {{ReferencingVersionCount}} = 0)
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_eq(referencing_step_count, 0)), _erb.erb_bool3(_erb.erb_eq(referencing_version_count, 0)))

def calc_resources_is_content_without_organization(description, artifact_type_concept, keywords, referencing_step_count, referencing_version_count):
    """
    TRUE when a resource has content but is not typed by the artifact scheme, has no keywords to be found by, or is linked to no procedure or step.
    
    Formula: =AND({{Description}} <> "", OR({{ArtifactTypeConcept}} = "", {{Keywords}} = "", ({{ReferencingStepCount}} + {{ReferencingVersionCount}}) = 0))
    """
    return _erb.erb_and(_erb.erb_bool3((not (description is None or description == ""))), _erb.erb_bool3(_erb.erb_or(_erb.erb_bool3((artifact_type_concept is None or artifact_type_concept == "")), _erb.erb_bool3((keywords is None or keywords == "")), _erb.erb_bool3(_erb.erb_eq(_erb.erb_add(referencing_step_count, referencing_version_count), 0)))))

def calc_resources_is_behind_current_practice(trailing_practice_count):
    """
    TRUE when the document has fallen behind how the work is currently done.
    
    Formula: ={{TrailingPracticeCount}} > 0
    """
    return _erb.erb_cmp(trailing_practice_count, '>', 0)


def compute_resources_fields(record: dict) -> dict:
    """
    Compute all calculated fields for Resources.
    
    Documents, datasets, APIs, templates, images, manuals, and operational records referenced by procedures. Maps to dcat:Resource.
    """
    result = dict(record)

    # Level 1 calculations
    try:
        result['name'] = calc_resources_name(result.get('title'))
    except Exception as _field_exc:
        result['name'] = None
        result.setdefault('_erb_errors', {})['name'] = str(_field_exc)
    try:
        result['is_approved_source'] = calc_resources_is_approved_source(result.get('approval_status'))
    except Exception as _field_exc:
        result['is_approved_source'] = None
        result.setdefault('_erb_errors', {})['is_approved_source'] = str(_field_exc)
    try:
        result['is_stale_extraction'] = calc_resources_is_stale_extraction(result.get('extracted_from_resource'), result.get('source_modified_at'), result.get('modified_at'))
    except Exception as _field_exc:
        result['is_stale_extraction'] = None
        result.setdefault('_erb_errors', {})['is_stale_extraction'] = str(_field_exc)
    try:
        result['is_unused_resource'] = calc_resources_is_unused_resource(result.get('referencing_step_count'), result.get('referencing_version_count'))
    except Exception as _field_exc:
        result['is_unused_resource'] = None
        result.setdefault('_erb_errors', {})['is_unused_resource'] = str(_field_exc)
    try:
        result['is_content_without_organization'] = calc_resources_is_content_without_organization(result.get('description'), result.get('artifact_type_concept'), result.get('keywords'), result.get('referencing_step_count'), result.get('referencing_version_count'))
    except Exception as _field_exc:
        result['is_content_without_organization'] = None
        result.setdefault('_erb_errors', {})['is_content_without_organization'] = str(_field_exc)
    try:
        result['is_behind_current_practice'] = calc_resources_is_behind_current_practice(result.get('trailing_practice_count'))
    except Exception as _field_exc:
        result['is_behind_current_practice'] = None
        result.setdefault('_erb_errors', {})['is_behind_current_practice'] = str(_field_exc)

    # Convert empty strings to None for string fields
    for key in ['name']:
        if result.get(key) == '':
            result[key] = None

    return result

