def calc_rulebook_fields_is_derived(field_type):
    """
    TRUE when this field is computed rather than stored.
    
    Formula: =OR({{FieldType}} = "calculated", {{FieldType}} = "lookup", {{FieldType}} = "aggregation")
    """
    return _erb.erb_or(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(field_type), 'calculated')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(field_type), 'lookup')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(field_type), 'aggregation')))

def calc_rulebook_fields_is_witness(invented_for_question):
    """
    TRUE when this field exists because a role asked a question. These are the fields the witness loops added.
    
    Formula: ={{InventedForQuestion}} <> "" 
    """
    return (not (invented_for_question is None or invented_for_question == ""))

def calc_rulebook_fields_is_substrate_contested(disagreeing_substrate_count):
    """
    True when at least one substrate disagrees about this field's values.
    
    Formula: ={{DisagreeingSubstrateCount}} > 0
    """
    return _erb.erb_cmp(disagreeing_substrate_count, '>', 0)

def calc_rulebook_fields_has_measured_data(measured_substantive_count):
    """
    TRUE when Postgres holds at least one substantive value (not blank, false or zero) for this field.
    
    Formula: ={{MeasuredSubstantiveCount}} > 0
    """
    return _erb.erb_cmp(_erb.erb_nullif(measured_substantive_count), '>', 0)

def calc_rulebook_fields_is_discriminating(measured_distinct_value_count):
    """
    TRUE when the field takes at least two distinct values over the seed data, so it can tell rows apart. An all-true or all-false witness states nothing.
    
    Formula: ={{MeasuredDistinctValueCount}} >= 2
    """
    return _erb.erb_cmp(_erb.erb_nullif(measured_distinct_value_count), '>=', 2)


def compute_rulebook_fields_fields(record: dict) -> dict:
    """
    Compute all calculated fields for RulebookFields.
    
    A complete census of every field in this rulebook. Reconciled from the real schemas by tools/reconcile_field_catalog.py — never hand-maintained. Fields invented by a witness loop carry an InventedForQuestion FK.
    """
    result = dict(record)

    # Level 1 calculations
    try:
        result['name'] = calc_rulebook_fields_name(result.get('target_table'), result.get('field_name'))
    except Exception as _field_exc:
        result['name'] = None
        result.setdefault('_erb_errors', {})['name'] = str(_field_exc)
    try:
        result['is_derived'] = calc_rulebook_fields_is_derived(result.get('field_type'))
    except Exception as _field_exc:
        result['is_derived'] = None
        result.setdefault('_erb_errors', {})['is_derived'] = str(_field_exc)
    try:
        result['is_witness'] = calc_rulebook_fields_is_witness(result.get('invented_for_question'))
    except Exception as _field_exc:
        result['is_witness'] = None
        result.setdefault('_erb_errors', {})['is_witness'] = str(_field_exc)
    try:
        result['is_substrate_contested'] = calc_rulebook_fields_is_substrate_contested(result.get('disagreeing_substrate_count'))
    except Exception as _field_exc:
        result['is_substrate_contested'] = None
        result.setdefault('_erb_errors', {})['is_substrate_contested'] = str(_field_exc)
    try:
        result['has_measured_data'] = calc_rulebook_fields_has_measured_data(result.get('measured_substantive_count'))
    except Exception as _field_exc:
        result['has_measured_data'] = None
        result.setdefault('_erb_errors', {})['has_measured_data'] = str(_field_exc)
    try:
        result['is_discriminating'] = calc_rulebook_fields_is_discriminating(result.get('measured_distinct_value_count'))
    except Exception as _field_exc:
        result['is_discriminating'] = None
        result.setdefault('_erb_errors', {})['is_discriminating'] = str(_field_exc)

    # Convert empty strings to None for string fields
    for key in ['name']:
        if result.get(key) == '':
            result[key] = None

    return result

