# =============================================================================
# SOURCEARTICLES
# The articles this rulebook was bootstrapped from. Coverage of each is computed from its claims; the article text itself is never stored.
# =============================================================================

# Level 1

def calc_source_articles_name(title):
    """
    Display name.
    
    Formula: ={{Title}}
    """
    return title

def calc_source_articles_uncovered_claim_count(claim_count, covered_claim_count):
    """
    Claims with no valid evidence.
    
    Formula: ={{ClaimCount}} - {{CoveredClaimCount}}
    """
    return _erb.erb_integer(_erb.erb_sub(claim_count, covered_claim_count))

def calc_source_articles_coverage_percent(claim_count, covered_claim_count):
    """
    Share of this article's claims that are covered.
    
    Formula: =IF({{ClaimCount}} = 0, 0, ROUND(100 * {{CoveredClaimCount}} / {{ClaimCount}}, 1))
    """
    return (0 if _erb.erb_bool3(_erb.erb_eq(claim_count, 0)) else _erb.erb_round(_erb.erb_div(_erb.erb_mul(100, covered_claim_count), claim_count), 1))

def calc_source_articles_agreed_coverage_percent(claim_count, agreed_claim_count):
    """
    Share of claims covered by evidence no graded substrate disputes.
    
    Formula: =IF({{ClaimCount}} = 0, 0, ROUND(100 * {{AgreedClaimCount}} / {{ClaimCount}}, 1))
    """
    return (0 if _erb.erb_bool3(_erb.erb_eq(claim_count, 0)) else _erb.erb_round(_erb.erb_div(_erb.erb_mul(100, agreed_claim_count), claim_count), 1))

# Level 2

def calc_source_articles_is_fully_covered(claim_count, uncovered_claim_count):
    """
    TRUE when every claim in this article is covered.
    
    Formula: =AND({{ClaimCount}} > 0, {{UncoveredClaimCount}} = 0)
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_cmp(claim_count, '>', 0)), _erb.erb_bool3(_erb.erb_eq(uncovered_claim_count, 0)))


def compute_source_articles_fields(record: dict) -> dict:
    """
    Compute all calculated fields for SourceArticles.
    
    The articles this rulebook was bootstrapped from. Coverage of each is computed from its claims; the article text itself is never stored.
    """
