# =============================================================================
# STEPVARIABLES
# Input and output variables a step declares (pplan:Variable, pplan:hasInputVar / hasOutputVar).
# =============================================================================

# Level 1

def calc_step_variables_name(step, direction, label):
    """
    Display name.
    
    Formula: ={{Step}} & " " & {{Direction}} & " " & {{Label}}
    """
    return (_erb.erb_text(step) + ' ' + _erb.erb_text(direction) + ' ' + _erb.erb_text(label))

def calc_step_variables_is_dangling_input(direction, source_variable, is_external_input):
    """
    TRUE for an input no earlier step produces and nobody declared as external: the step cannot be run as specified.
    
    Formula: =AND({{Direction}} = "Input", {{SourceVariable}} = "", {{IsExternalInput}} = FALSE)
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(direction), 'Input')), _erb.erb_bool3((source_variable is None or source_variable == "")), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(is_external_input), False)))

def calc_step_variables_is_miswired_source(source_variable, source_direction):
    """
    TRUE when an input is fed from a variable that is not an output.
    
    Formula: =AND({{SourceVariable}} <> "", {{SourceDirection}} <> "Output")
    """
    return _erb.erb_and(_erb.erb_bool3((not (source_variable is None or source_variable == ""))), _erb.erb_bool3(_erb.erb_ne(source_direction, 'Output')))

def calc_step_variables_input_step_key(direction, step):
    """
    Step key for an input variable.
    
    Formula: =IF({{Direction}} = "Input", {{Step}}, "")
    """
    return (step if _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(direction), 'Input')) else '')

def calc_step_variables_output_step_key(direction, step):
    """
    Step key for an output variable.
    
    Formula: =IF({{Direction}} = "Output", {{Step}}, "")
    """
    return (step if _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(direction), 'Output')) else '')

def calc_step_variables_is_input_from_ai_artifact(direction, source_step_agent_kind):
    """
    TRUE for an input fed by an artifact that a step held by an AI agent produces.
    
    Formula: =AND({{Direction}} = "Input", {{SourceStepAgentKind}} = "AIAgent")
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(direction), 'Input')), _erb.erb_bool3(_erb.erb_eq(source_step_agent_kind, 'AIAgent')))

# Level 2

def calc_step_variables_ai_artifact_consumer_has_no_accountable_agent(is_input_from_ai_artifact, step_accountable_agent):
    """
    TRUE when a step consuming an AI agent's artifact has nobody holding its role.
    
    Formula: =AND({{IsInputFromAiArtifact}}, {{StepAccountableAgent}} = "")
    """
    return _erb.erb_and(_erb.erb_bool3(is_input_from_ai_artifact), _erb.erb_bool3((step_accountable_agent is None or step_accountable_agent == "")))

def calc_step_variables_ai_blast_radius_path(is_input_from_ai_artifact, source_step_agent, label, step, consumer_role, step_accountable_agent, consumer_workflow):
    """
    For an input fed by an AI agent's artifact: the agent, the artifact, the consuming step, its role, its agent and its workflow.
    
    Formula: =IF({{IsInputFromAiArtifact}}, {{SourceStepAgent}} & " produces " & {{Label}} & " for " & {{Step}} & "; role " & {{ConsumerRole}} & "; agent " & {{StepAccountableAgent}} & "; workflow " & {{ConsumerWorkflow}}, "")
    """
    return ((_erb.erb_text(source_step_agent) + ' produces ' + _erb.erb_text(label) + ' for ' + _erb.erb_text(step) + '; role ' + _erb.erb_text(consumer_role) + '; agent ' + _erb.erb_text(step_accountable_agent) + '; workflow ' + _erb.erb_text(consumer_workflow)) if _erb.erb_bool3(is_input_from_ai_artifact) else '')


def compute_step_variables_fields(record: dict) -> dict:
    """
    Compute all calculated fields for StepVariables.
    
    Input and output variables a step declares (pplan:Variable, pplan:hasInputVar / hasOutputVar).
    """
    result = dict(record)

    # Level 1 calculations
    try:
        result['name'] = calc_step_variables_name(result.get('step'), result.get('direction'), result.get('label'))
    except Exception as _field_exc:
        result['name'] = None
        result.setdefault('_erb_errors', {})['name'] = str(_field_exc)
    try:
        result['is_dangling_input'] = calc_step_variables_is_dangling_input(result.get('direction'), result.get('source_variable'), result.get('is_external_input'))
    except Exception as _field_exc:
        result['is_dangling_input'] = None
        result.setdefault('_erb_errors', {})['is_dangling_input'] = str(_field_exc)
    try:
        result['is_miswired_source'] = calc_step_variables_is_miswired_source(result.get('source_variable'), result.get('source_direction'))
    except Exception as _field_exc:
        result['is_miswired_source'] = None
        result.setdefault('_erb_errors', {})['is_miswired_source'] = str(_field_exc)
    try:
        result['input_step_key'] = calc_step_variables_input_step_key(result.get('direction'), result.get('step'))
    except Exception as _field_exc:
        result['input_step_key'] = None
        result.setdefault('_erb_errors', {})['input_step_key'] = str(_field_exc)
    try:
        result['output_step_key'] = calc_step_variables_output_step_key(result.get('direction'), result.get('step'))
    except Exception as _field_exc:
        result['output_step_key'] = None
        result.setdefault('_erb_errors', {})['output_step_key'] = str(_field_exc)
    try:
        result['is_input_from_ai_artifact'] = calc_step_variables_is_input_from_ai_artifact(result.get('direction'), result.get('source_step_agent_kind'))
    except Exception as _field_exc:
        result['is_input_from_ai_artifact'] = None
        result.setdefault('_erb_errors', {})['is_input_from_ai_artifact'] = str(_field_exc)

    # Level 2 calculations
    try:
        result['ai_artifact_consumer_has_no_accountable_agent'] = calc_step_variables_ai_artifact_consumer_has_no_accountable_agent(result.get('is_input_from_ai_artifact'), result.get('step_accountable_agent'))
    except Exception as _field_exc:
        result['ai_artifact_consumer_has_no_accountable_agent'] = None
        result.setdefault('_erb_errors', {})['ai_artifact_consumer_has_no_accountable_agent'] = str(_field_exc)
    try:
        result['ai_blast_radius_path'] = calc_step_variables_ai_blast_radius_path(result.get('is_input_from_ai_artifact'), result.get('source_step_agent'), result.get('label'), result.get('step'), result.get('consumer_role'), result.get('step_accountable_agent'), result.get('consumer_workflow'))
    except Exception as _field_exc:
        result['ai_blast_radius_path'] = None
        result.setdefault('_erb_errors', {})['ai_blast_radius_path'] = str(_field_exc)

    # Convert empty strings to None for string fields
    for key in ['name', 'input_step_key', 'output_step_key', 'ai_blast_radius_path']:
        if result.get(key) == '':
            result[key] = None

    return result

# =============================================================================
# EXECUTIONENTITIES
# Entities a step execution used or generated (prov:used, prov:wasGeneratedBy, pplan:correspondsToVariable).
# =============================================================================

# Level 1

def calc_execution_entities_name(step_execution, usage, entity_label):
    """
    Display name.
    
    Formula: ={{StepExecution}} & " " & {{Usage}} & " " & {{EntityLabel}}
    """
    return (_erb.erb_text(step_execution) + ' ' + _erb.erb_text(usage) + ' ' + _erb.erb_text(entity_label))

def calc_execution_entities_is_usage_direction_mismatch(usage, variable_direction):
    """
    TRUE when a used entity maps to an output or a generated entity maps to an input.
    
    Formula: =OR(AND({{Usage}} = "Used", {{VariableDirection}} <> "Input"), AND({{Usage}} = "Generated", {{VariableDirection}} <> "Output"))
    """
    return _erb.erb_or(_erb.erb_bool3(_erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(usage), 'Used')), _erb.erb_bool3(_erb.erb_ne(variable_direction, 'Input')))), _erb.erb_bool3(_erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(usage), 'Generated')), _erb.erb_bool3(_erb.erb_ne(variable_direction, 'Output')))))

def calc_execution_entities_is_foreign_variable(variable_step, executed_step):
    """
    TRUE when the entity corresponds to a variable another step declares.
    
    Formula: ={{VariableStep}} <> {{ExecutedStep}}
    """
    return _erb.erb_ne(variable_step, executed_step)

def calc_execution_entities_used_execution_key(usage, step_execution):
    """
    Step execution key for a used entity.
    
    Formula: =IF({{Usage}} = "Used", {{StepExecution}}, "")
    """
    return (step_execution if _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(usage), 'Used')) else '')

def calc_execution_entities_generated_execution_key(usage, step_execution):
    """
    Step execution key for a generated entity.
    
    Formula: =IF({{Usage}} = "Generated", {{StepExecution}}, "")
    """
    return (step_execution if _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(usage), 'Generated')) else '')

def calc_execution_entities_violates_declared_datatype_or_format(recorded_datatype, variable_datatype, recorded_format, variable_expected_format):
    """
    TRUE when a recorded value's datatype or format differs from what its variable declares.
    
    Formula: =OR(AND({{RecordedDatatype}} <> "", {{RecordedDatatype}} <> {{VariableDatatype}}), AND({{RecordedFormat}} <> "", {{VariableExpectedFormat}} <> "", {{RecordedFormat}} <> {{VariableExpectedFormat}}))
    """
    return _erb.erb_or(_erb.erb_bool3(_erb.erb_and(_erb.erb_bool3((not (recorded_datatype is None or recorded_datatype == ""))), _erb.erb_bool3(_erb.erb_ne(_erb.erb_nullif(recorded_datatype), variable_datatype)))), _erb.erb_bool3(_erb.erb_and(_erb.erb_bool3((not (recorded_format is None or recorded_format == ""))), _erb.erb_bool3((not (variable_expected_format is None or variable_expected_format == ""))), _erb.erb_bool3(_erb.erb_ne(_erb.erb_nullif(recorded_format), variable_expected_format)))))

def calc_execution_entities_attributed_to_agent(usage, generating_agent):
    """
    For a generated entity, the agent it is attributed to (prov:wasAttributedTo).
    
    Formula: =IF({{Usage}} = "Generated", {{GeneratingAgent}}, "")
    """
    return (generating_agent if _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(usage), 'Generated')) else '')


def compute_execution_entities_fields(record: dict) -> dict:
    """
    Compute all calculated fields for ExecutionEntities.
    
    Entities a step execution used or generated (prov:used, prov:wasGeneratedBy, pplan:correspondsToVariable).
    """
