# =============================================================================
# COLLECTEDSOURCEMATERIALS
# Raw material collection produced, and when it was organized into a scheme and encoded into a procedure version.
# =============================================================================

# Level 1

def calc_collected_source_materials_name(label):
    """
    Display name.
    
    Formula: ={{Label}}
    """
    return label

def calc_collected_source_materials_is_modeled_before_organized(encoded_into_version, organized_at, encoded_at):
    """
    TRUE when material was encoded into a procedure version before it was organized, or without ever being organized.
    
    Formula: =AND({{EncodedIntoVersion}} <> "", OR({{OrganizedAt}} = "", {{EncodedAt}} < {{OrganizedAt}}))
    """
    return _erb.erb_and(_erb.erb_bool3((not (encoded_into_version is None or encoded_into_version == ""))), _erb.erb_bool3(_erb.erb_or(_erb.erb_bool3((organized_at is None or organized_at == "")), _erb.erb_bool3(_erb.erb_cmp(_erb.erb_nullif(encoded_at), '<', _erb.erb_nullif(organized_at))))))

def calc_collected_source_materials_is_document_source(material_kind):
    """
    TRUE for an excerpt of existing written material.
    
    Formula: ={{MaterialKind}} = "DocumentExcerpt" 
    """
    return _erb.erb_eq(_erb.erb_nullif(material_kind), 'DocumentExcerpt')

def calc_collected_source_materials_is_people_capture(material_kind):
    """
    TRUE for material captured from people: a transcript or field notes.
    
    Formula: =OR({{MaterialKind}} = "Transcript", {{MaterialKind}} = "FieldNotes")
    """
    return _erb.erb_or(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(material_kind), 'Transcript')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(material_kind), 'FieldNotes')))

def calc_collected_source_materials_is_practice_evidence(material_kind):
    """
    TRUE for material that records the work as performed: field notes or a mined event trace.
    
    Formula: =OR({{MaterialKind}} = "FieldNotes", {{MaterialKind}} = "MinedEventTrace")
    """
    return _erb.erb_or(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(material_kind), 'FieldNotes')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(material_kind), 'MinedEventTrace')))

def calc_collected_source_materials_is_captured_in_flow_of_work(captured_during_execution):
    """
    TRUE when the material was captured while the work was being done.
    
    Formula: ={{CapturedDuringExecution}} <> "" 
    """
    return (not (captured_during_execution is None or captured_during_execution == ""))

def calc_collected_source_materials_is_dependency_invisible_to_change(encoded_into_version, dependent_trace_count):
    """
    TRUE when the material was encoded into a model but no trace records what rests on it, so a change to it reveals nothing.
    
    Formula: =AND({{EncodedIntoVersion}} <> "", {{DependentTraceCount}} = 0)
    """
    return _erb.erb_and(_erb.erb_bool3((not (encoded_into_version is None or encoded_into_version == ""))), _erb.erb_bool3(_erb.erb_eq(dependent_trace_count, 0)))

def calc_collected_source_materials_has_knowledge_affected_by_source_change(changed_dependent_count):
    """
    TRUE when a revision of the source affects organized knowledge taken from it.
    
    Formula: ={{ChangedDependentCount}} > 0
    """
    return _erb.erb_cmp(changed_dependent_count, '>', 0)


def compute_collected_source_materials_fields(record: dict) -> dict:
    """
    Compute all calculated fields for CollectedSourceMaterials.
    
    Raw material collection produced, and when it was organized into a scheme and encoded into a procedure version.
    """
    result = dict(record)

    # Level 1 calculations
    try:
        result['name'] = calc_collected_source_materials_name(result.get('label'))
    except Exception as _field_exc:
        result['name'] = None
        result.setdefault('_erb_errors', {})['name'] = str(_field_exc)
    try:
        result['is_modeled_before_organized'] = calc_collected_source_materials_is_modeled_before_organized(result.get('encoded_into_version'), result.get('organized_at'), result.get('encoded_at'))
    except Exception as _field_exc:
        result['is_modeled_before_organized'] = None
        result.setdefault('_erb_errors', {})['is_modeled_before_organized'] = str(_field_exc)
    try:
        result['is_document_source'] = calc_collected_source_materials_is_document_source(result.get('material_kind'))
    except Exception as _field_exc:
        result['is_document_source'] = None
        result.setdefault('_erb_errors', {})['is_document_source'] = str(_field_exc)
    try:
        result['is_people_capture'] = calc_collected_source_materials_is_people_capture(result.get('material_kind'))
    except Exception as _field_exc:
        result['is_people_capture'] = None
        result.setdefault('_erb_errors', {})['is_people_capture'] = str(_field_exc)
    try:
        result['is_practice_evidence'] = calc_collected_source_materials_is_practice_evidence(result.get('material_kind'))
    except Exception as _field_exc:
        result['is_practice_evidence'] = None
        result.setdefault('_erb_errors', {})['is_practice_evidence'] = str(_field_exc)
    try:
        result['is_captured_in_flow_of_work'] = calc_collected_source_materials_is_captured_in_flow_of_work(result.get('captured_during_execution'))
    except Exception as _field_exc:
        result['is_captured_in_flow_of_work'] = None
        result.setdefault('_erb_errors', {})['is_captured_in_flow_of_work'] = str(_field_exc)
    try:
        result['is_dependency_invisible_to_change'] = calc_collected_source_materials_is_dependency_invisible_to_change(result.get('encoded_into_version'), result.get('dependent_trace_count'))
    except Exception as _field_exc:
        result['is_dependency_invisible_to_change'] = None
        result.setdefault('_erb_errors', {})['is_dependency_invisible_to_change'] = str(_field_exc)
    try:
        result['has_knowledge_affected_by_source_change'] = calc_collected_source_materials_has_knowledge_affected_by_source_change(result.get('changed_dependent_count'))
    except Exception as _field_exc:
        result['has_knowledge_affected_by_source_change'] = None
        result.setdefault('_erb_errors', {})['has_knowledge_affected_by_source_change'] = str(_field_exc)

    # Convert empty strings to None for string fields
    for key in ['name']:
        if result.get(key) == '':
            result[key] = None

    return result

