# =============================================================================
# TERMLABELVARIANTS
# Preferred and alternative labels of a controlled concept, one row per wording, so variant wordings can be matched.
# =============================================================================

# Level 1

def calc_term_label_variants_name(vocabulary_term, label_kind, wording):
    """
    Display name.
    
    Formula: ={{VocabularyTerm}} & " " & {{LabelKind}} & ": " & {{Wording}}
    """
    return (_erb.erb_text(vocabulary_term) + ' ' + _erb.erb_text(label_kind) + ': ' + _erb.erb_text(wording))

def calc_term_label_variants_wording_key(term_scheme, wording):
    """
    Scheme and wording.
    
    Formula: ={{TermScheme}} & "|" & {{Wording}}
    """
    return (_erb.erb_text(term_scheme) + '|' + _erb.erb_text(wording))

def calc_term_label_variants_is_ambiguous_label(concepts_sharing_wording):
    """
    TRUE when one wording is a label of more than one concept in the scheme, so it cannot normalize to one canonical concept.
    
    Formula: ={{ConceptsSharingWording}} > 1
    """
    return _erb.erb_cmp(concepts_sharing_wording, '>', 1)

def calc_term_label_variants_pref_wording(label_kind, wording):
    """
    Wording of a preferred label, regardless of scheme.
    
    Formula: =IF({{LabelKind}} = "pref", {{Wording}}, "")
    """
    return (wording if _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(label_kind), 'pref')) else '')

def calc_term_label_variants_is_cross_scheme_duplicate_pref(label_kind, same_pref_wording_count):
    """
    TRUE when the same concern is defined as a separate preferred concept in more than one scheme instead of being shared.
    
    Formula: =AND({{LabelKind}} = "pref", {{SamePrefWordingCount}} > 1)
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(label_kind), 'pref')), _erb.erb_bool3(_erb.erb_cmp(same_pref_wording_count, '>', 1)))

# Level 2

def calc_term_label_variants_pref_wording_key(label_kind, wording_key):
    """
    Scheme and wording for a preferred label.
    
    Formula: =IF({{LabelKind}} = "pref", {{WordingKey}}, "")
    """
    return (wording_key if _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(label_kind), 'pref')) else '')


def compute_term_label_variants_fields(record: dict) -> dict:
    """
    Compute all calculated fields for TermLabelVariants.
    
    Preferred and alternative labels of a controlled concept, one row per wording, so variant wordings can be matched.
    """
    result = dict(record)

    # Level 1 calculations
    try:
        result['name'] = calc_term_label_variants_name(result.get('vocabulary_term'), result.get('label_kind'), result.get('wording'))
    except Exception as _field_exc:
        result['name'] = None
        result.setdefault('_erb_errors', {})['name'] = str(_field_exc)
    try:
        result['wording_key'] = calc_term_label_variants_wording_key(result.get('term_scheme'), result.get('wording'))
    except Exception as _field_exc:
        result['wording_key'] = None
        result.setdefault('_erb_errors', {})['wording_key'] = str(_field_exc)
    try:
        result['is_ambiguous_label'] = calc_term_label_variants_is_ambiguous_label(result.get('concepts_sharing_wording'))
    except Exception as _field_exc:
        result['is_ambiguous_label'] = None
        result.setdefault('_erb_errors', {})['is_ambiguous_label'] = str(_field_exc)
    try:
        result['pref_wording'] = calc_term_label_variants_pref_wording(result.get('label_kind'), result.get('wording'))
    except Exception as _field_exc:
        result['pref_wording'] = None
        result.setdefault('_erb_errors', {})['pref_wording'] = str(_field_exc)
    try:
        result['is_cross_scheme_duplicate_pref'] = calc_term_label_variants_is_cross_scheme_duplicate_pref(result.get('label_kind'), result.get('same_pref_wording_count'))
    except Exception as _field_exc:
        result['is_cross_scheme_duplicate_pref'] = None
        result.setdefault('_erb_errors', {})['is_cross_scheme_duplicate_pref'] = str(_field_exc)

    # Level 2 calculations
    try:
        result['pref_wording_key'] = calc_term_label_variants_pref_wording_key(result.get('label_kind'), result.get('wording_key'))
    except Exception as _field_exc:
        result['pref_wording_key'] = None
        result.setdefault('_erb_errors', {})['pref_wording_key'] = str(_field_exc)

    # Convert empty strings to None for string fields
    for key in ['name', 'wording_key', 'pref_wording_key', 'pref_wording']:
        if result.get(key) == '':
            result[key] = None

    return result

# =============================================================================
# AILABELINGRUNS
# A run in which an AI model assigned controlled values, with or without a grounding scheme.
# =============================================================================

# Level 1

def calc_ai_labeling_runs_name(agent, run_at):
    """
    Display name.
    
    Formula: ={{Agent}} & " " & {{RunAt}}
    """
    return (_erb.erb_text(agent) + ' ' + _erb.erb_datetime_text(run_at))

def calc_ai_labeling_runs_is_ungrounded_synonym_sprawl(grounding_scheme, non_canonical_output_count):
    """
    TRUE when an ungrounded run produced values outside the canonical scheme.
    
    Formula: =AND({{GroundingScheme}} = "", {{NonCanonicalOutputCount}} > 0)
    """
    return _erb.erb_and(_erb.erb_bool3((grounding_scheme is None or grounding_scheme == "")), _erb.erb_bool3(_erb.erb_cmp(non_canonical_output_count, '>', 0)))

def calc_ai_labeling_runs_grounded_in_non_machine_readable_scheme(grounding_scheme, grounding_scheme_is_machine_accessible):
    """
    TRUE when a run was grounded in a vocabulary that is not formal and machine-accessible.
    
    Formula: =AND({{GroundingScheme}} <> "", {{GroundingSchemeIsMachineAccessible}} = FALSE)
    """
    return _erb.erb_and(_erb.erb_bool3((not (grounding_scheme is None or grounding_scheme == ""))), _erb.erb_bool3(_erb.erb_eq(grounding_scheme_is_machine_accessible, False)))


def compute_ai_labeling_runs_fields(record: dict) -> dict:
    """
    Compute all calculated fields for AiLabelingRuns.
    
    A run in which an AI model assigned controlled values, with or without a grounding scheme.
    """
    result = dict(record)

    # Level 1 calculations
    try:
        result['name'] = calc_ai_labeling_runs_name(result.get('agent'), result.get('run_at'))
    except Exception as _field_exc:
        result['name'] = None
        result.setdefault('_erb_errors', {})['name'] = str(_field_exc)
    try:
        result['is_ungrounded_synonym_sprawl'] = calc_ai_labeling_runs_is_ungrounded_synonym_sprawl(result.get('grounding_scheme'), result.get('non_canonical_output_count'))
    except Exception as _field_exc:
        result['is_ungrounded_synonym_sprawl'] = None
        result.setdefault('_erb_errors', {})['is_ungrounded_synonym_sprawl'] = str(_field_exc)
    try:
        result['grounded_in_non_machine_readable_scheme'] = calc_ai_labeling_runs_grounded_in_non_machine_readable_scheme(result.get('grounding_scheme'), result.get('grounding_scheme_is_machine_accessible'))
    except Exception as _field_exc:
        result['grounded_in_non_machine_readable_scheme'] = None
        result.setdefault('_erb_errors', {})['grounded_in_non_machine_readable_scheme'] = str(_field_exc)

    # Convert empty strings to None for string fields
    for key in ['name']:
        if result.get(key) == '':
            result[key] = None

    return result

# =============================================================================
# SOURCETERMMENTIONS
# A wording found in collected material or produced by an AI run, and the concept a knowledge engineer judged it to mean.
# =============================================================================

# Level 1

def calc_source_term_mentions_name(concept_scheme, wording):
    """
    Display name.
    
    Formula: ={{ConceptScheme}} & ": " & {{Wording}}
    """
    return (_erb.erb_text(concept_scheme) + ': ' + _erb.erb_text(wording))

def calc_source_term_mentions_wording_key(concept_scheme, wording):
    """
    Scheme and wording.
    
    Formula: ={{ConceptScheme}} & "|" & {{Wording}}
    """
    return (_erb.erb_text(concept_scheme) + '|' + _erb.erb_text(wording))

def calc_source_term_mentions_is_uncontrolled_wording(matching_label_count):
    """
    TRUE when a wording resolves to no concept label in its scheme.
    
    Formula: ={{MatchingLabelCount}} = 0
    """
    return _erb.erb_eq(matching_label_count, 0)

def calc_source_term_mentions_is_non_canonical_generated_value(mention_origin, matching_pref_label_count):
    """
    TRUE when an AI-generated value is not a preferred label of the governed scheme.
    
    Formula: =AND({{MentionOrigin}} = "AIGenerated", {{MatchingPrefLabelCount}} = 0)
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(mention_origin), 'AIGenerated')), _erb.erb_bool3(_erb.erb_eq(matching_pref_label_count, 0)))

def calc_source_term_mentions_unresolved_intended_term_key(matching_label_count, intended_term):
    """
    Intended concept key when the wording does not resolve.
    
    Formula: =IF({{MatchingLabelCount}} = 0, {{IntendedTerm}}, "")
    """
    return (intended_term if _erb.erb_bool3(_erb.erb_eq(matching_label_count, 0)) else '')

def calc_source_term_mentions_unresolved_role_key(matching_label_count, intended_term_role):
    """
    Role key when a role wording does not resolve.
    
    Formula: =IF({{MatchingLabelCount}} = 0, {{IntendedTermRole}}, "")
    """
    return (intended_term_role if _erb.erb_bool3(_erb.erb_eq(matching_label_count, 0)) else '')


def compute_source_term_mentions_fields(record: dict) -> dict:
    """
    Compute all calculated fields for SourceTermMentions.
    
    A wording found in collected material or produced by an AI run, and the concept a knowledge engineer judged it to mean.
    """
    result = dict(record)

    # Level 1 calculations
    try:
        result['name'] = calc_source_term_mentions_name(result.get('concept_scheme'), result.get('wording'))
    except Exception as _field_exc:
        result['name'] = None
        result.setdefault('_erb_errors', {})['name'] = str(_field_exc)
    try:
        result['wording_key'] = calc_source_term_mentions_wording_key(result.get('concept_scheme'), result.get('wording'))
    except Exception as _field_exc:
        result['wording_key'] = None
        result.setdefault('_erb_errors', {})['wording_key'] = str(_field_exc)
    try:
        result['is_uncontrolled_wording'] = calc_source_term_mentions_is_uncontrolled_wording(result.get('matching_label_count'))
    except Exception as _field_exc:
        result['is_uncontrolled_wording'] = None
        result.setdefault('_erb_errors', {})['is_uncontrolled_wording'] = str(_field_exc)
    try:
        result['is_non_canonical_generated_value'] = calc_source_term_mentions_is_non_canonical_generated_value(result.get('mention_origin'), result.get('matching_pref_label_count'))
    except Exception as _field_exc:
        result['is_non_canonical_generated_value'] = None
        result.setdefault('_erb_errors', {})['is_non_canonical_generated_value'] = str(_field_exc)
    try:
        result['unresolved_intended_term_key'] = calc_source_term_mentions_unresolved_intended_term_key(result.get('matching_label_count'), result.get('intended_term'))
    except Exception as _field_exc:
        result['unresolved_intended_term_key'] = None
        result.setdefault('_erb_errors', {})['unresolved_intended_term_key'] = str(_field_exc)
    try:
        result['unresolved_role_key'] = calc_source_term_mentions_unresolved_role_key(result.get('matching_label_count'), result.get('intended_term_role'))
    except Exception as _field_exc:
        result['unresolved_role_key'] = None
        result.setdefault('_erb_errors', {})['unresolved_role_key'] = str(_field_exc)

    # Convert empty strings to None for string fields
    for key in ['name', 'wording_key', 'unresolved_intended_term_key', 'unresolved_role_key']:
        if result.get(key) == '':
            result[key] = None

    return result

