    # Level 1 calculations
    try:
        result['name'] = calc_external_standard_terms_name(result.get('term_iri'))
    except Exception as _field_exc:
        result['name'] = None
        result.setdefault('_erb_errors', {})['name'] = str(_field_exc)
    try:
        result['days_since_deprecated'] = calc_external_standard_terms_days_since_deprecated(result.get('deprecated_at'), result.get('as_of_instant'))
    except Exception as _field_exc:
        result['days_since_deprecated'] = None
        result.setdefault('_erb_errors', {})['days_since_deprecated'] = str(_field_exc)
    try:
        result['is_adopted_but_deprecated'] = calc_external_standard_terms_is_adopted_but_deprecated(result.get('deprecated_by_source'), result.get('using_mapping_count'), result.get('rehomed_as_term'))
    except Exception as _field_exc:
        result['is_adopted_but_deprecated'] = None
        result.setdefault('_erb_errors', {})['is_adopted_but_deprecated'] = str(_field_exc)
    try:
        result['is_alignment_stale_after_deprecation'] = calc_external_standard_terms_is_alignment_stale_after_deprecation(result.get('deprecated_by_source'), result.get('alignment_updated_at'), result.get('deprecated_at'))
    except Exception as _field_exc:
        result['is_alignment_stale_after_deprecation'] = None
        result.setdefault('_erb_errors', {})['is_alignment_stale_after_deprecation'] = str(_field_exc)
    try:
        result['is_needed_deprecated_term_not_rehomed'] = calc_external_standard_terms_is_needed_deprecated_term_not_rehomed(result.get('deprecated_by_source'), result.get('model_still_needs_term'), result.get('rehomed_as_term'))
    except Exception as _field_exc:
        result['is_needed_deprecated_term_not_rehomed'] = None
        result.setdefault('_erb_errors', {})['is_needed_deprecated_term_not_rehomed'] = str(_field_exc)
    try:
        result['is_rehomed_without_identity_link'] = calc_external_standard_terms_is_rehomed_without_identity_link(result.get('rehomed_as_term'), result.get('rehomed_term_same_as'), result.get('term_iri'))
    except Exception as _field_exc:
        result['is_rehomed_without_identity_link'] = None
        result.setdefault('_erb_errors', {})['is_rehomed_without_identity_link'] = str(_field_exc)
    try:
        result['is_rehomed_without_new_release'] = calc_external_standard_terms_is_rehomed_without_new_release(result.get('rehomed_as_term'), result.get('rehomed_term_release_issued_at'), result.get('deprecated_at'))
    except Exception as _field_exc:
        result['is_rehomed_without_new_release'] = None
        result.setdefault('_erb_errors', {})['is_rehomed_without_new_release'] = str(_field_exc)
    try:
        result['has_unpropagated_identifier_change'] = calc_external_standard_terms_has_unpropagated_identifier_change(result.get('previous_term_iri'), result.get('stale_identifier_mapping_count'))
    except Exception as _field_exc:
        result['has_unpropagated_identifier_change'] = None
        result.setdefault('_erb_errors', {})['has_unpropagated_identifier_change'] = str(_field_exc)
    try:
        result['rehoming_kept_external_namespace'] = calc_external_standard_terms_rehoming_kept_external_namespace(result.get('rehomed_as_term'), result.get('rehomed_term_namespace'), result.get('profile_namespace_iri'))
    except Exception as _field_exc:
        result['rehoming_kept_external_namespace'] = None
        result.setdefault('_erb_errors', {})['rehoming_kept_external_namespace'] = str(_field_exc)

    # Level 2 calculations
    try:
        result['is_recent_deprecation'] = calc_external_standard_terms_is_recent_deprecation(result.get('deprecated_by_source'), result.get('deprecated_at'), result.get('days_since_deprecated'))
    except Exception as _field_exc:
        result['is_recent_deprecation'] = None
        result.setdefault('_erb_errors', {})['is_recent_deprecation'] = str(_field_exc)

    # Convert empty strings to None for string fields
    for key in ['name']:
        if result.get(key) == '':
            result[key] = None

    return result

