# =============================================================================
# MODELCHANGEREQUESTS
# Requests to change a governed model, each begun from a stated need and tied to the competency question that motivates it.
# =============================================================================

# Level 1

def calc_model_change_requests_name(title):
    """
    Display name.
    
    Formula: ={{Title}}
    """
    return title

def calc_model_change_requests_rule_key(governed_model, change_layer):
    """
    Key of the change-authority rule for this model and layer.
    
    Formula: ={{GovernedModel}} & "|" & {{ChangeLayer}}
    """
    return (_erb.erb_text(governed_model) + '|' + _erb.erb_text(change_layer))

def calc_model_change_requests_is_accepted(status):
    """
    TRUE once approved or deployed.
    
    Formula: =OR({{Status}} = "Approved", {{Status}} = "Deployed")
    """
    return _erb.erb_or(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(status), 'Approved')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(status), 'Deployed')))

def calc_model_change_requests_is_modeling_change(classification):
    """
    TRUE for a modeling change rather than a data operation.
    
    Formula: ={{Classification}} = "ModelingChange" 
    """
    return _erb.erb_eq(_erb.erb_nullif(classification), 'ModelingChange')

def calc_model_change_requests_is_schema_change(change_layer):
    """
    TRUE for a change to the schema layer.
    
    Formula: ={{ChangeLayer}} = "Schema" 
    """
    return _erb.erb_eq(_erb.erb_nullif(change_layer), 'Schema')

def calc_model_change_requests_has_authority_review(authority_reviewed_at):
    """
    TRUE when the authority reviewed the change.
    
    Formula: ={{AuthorityReviewedAt}} <> "" 
    """
    return (not (authority_reviewed_at is None or authority_reviewed_at == ""))

def calc_model_change_requests_requires_authority_review(change_operation, declared_scale):
    """
    TRUE when the change alters or retires existing elements or vocabularies, adds disjointness, or is major.
    
    Formula: =OR({{ChangeOperation}} = "RenameClass", {{ChangeOperation}} = "RemoveClass", {{ChangeOperation}} = "ChangeDomainRange", {{ChangeOperation}} = "AddDisjointness", {{ChangeOperation}} = "AddVocabularyTerm", {{ChangeOperation}} = "RetireDefinition", {{DeclaredScale}} = "Major")
    """
    return _erb.erb_or(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'RenameClass')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'RemoveClass')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'ChangeDomainRange')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'AddDisjointness')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'AddVocabularyTerm')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'RetireDefinition')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(declared_scale), 'Major')))

def calc_model_change_requests_placement_not_decided_by_authority(implementation_placement, placement_decided_by_agent, authority_agent):
    """
    TRUE when someone other than the authority decided how and where a change is made.
    
    Formula: =AND({{ImplementationPlacement}} <> "", {{PlacementDecidedByAgent}} <> {{AuthorityAgent}})
    """
    return _erb.erb_and(_erb.erb_bool3((not (implementation_placement is None or implementation_placement == ""))), _erb.erb_bool3(_erb.erb_ne(_erb.erb_nullif(placement_decided_by_agent), authority_agent)))

def calc_model_change_requests_is_misrouted(required_route, route):
    """
    TRUE when a change went through a different process than the rule for its layer requires.
    
    Formula: =AND({{RequiredRoute}} <> "", {{Route}} <> {{RequiredRoute}})
    """
    return _erb.erb_and(_erb.erb_bool3((not (required_route is None or required_route == ""))), _erb.erb_bool3(_erb.erb_ne(_erb.erb_nullif(route), required_route)))

def calc_model_change_requests_lacks_motivating_question(motivating_question):
    """
    TRUE when the request names no competency question.
    
    Formula: ={{MotivatingQuestion}} = "" 
    """
    return (motivating_question is None or motivating_question == "")

def calc_model_change_requests_motivated_by_failing_question(motivating_question, motivation_kind):
    """
    TRUE when the change exists because a question the model used to answer now fails.
    
    Formula: =AND({{MotivatingQuestion}} <> "", {{MotivationKind}} = "ExistingQuestionNowFails")
    """
    return _erb.erb_and(_erb.erb_bool3((not (motivating_question is None or motivating_question == ""))), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(motivation_kind), 'ExistingQuestionNowFails')))

def calc_model_change_requests_is_misclassified_agent_swap(change_operation, classification):
    """
    TRUE when swapping which agent fills a role was handled as a modeling change.
    
    Formula: =AND({{ChangeOperation}} = "ReassignAgent", {{Classification}} <> "DataOperation")
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'ReassignAgent')), _erb.erb_bool3(_erb.erb_ne(_erb.erb_nullif(classification), 'DataOperation')))

def calc_model_change_requests_ai_to_human_move_without_compliance_review(change_operation, compliance_impact):
    """
    TRUE when a step moved from AI to human execution with no compliance consequences recorded.
    
    Formula: =AND({{ChangeOperation}} = "MoveStepToHuman", {{ComplianceImpact}} = "")
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'MoveStepToHuman')), _erb.erb_bool3((compliance_impact is None or compliance_impact == "")))

def calc_model_change_requests_ai_to_human_move_unaudited(change_operation, effective_at, stated_need):
    """
    TRUE when a move from AI to human execution does not record when it took effect or why.
    
    Formula: =AND({{ChangeOperation}} = "MoveStepToHuman", OR({{EffectiveAt}} = "", {{StatedNeed}} = ""))
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'MoveStepToHuman')), _erb.erb_bool3(_erb.erb_or(_erb.erb_bool3((effective_at is None or effective_at == "")), _erb.erb_bool3((stated_need is None or stated_need == "")))))

def calc_model_change_requests_is_ai_to_human_move(change_operation, effective_at):
    """
    TRUE for a recorded move of a step from AI to human execution with its effective date.
    
    Formula: =AND({{ChangeOperation}} = "MoveStepToHuman", {{EffectiveAt}} <> "")
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'MoveStepToHuman')), _erb.erb_bool3((not (effective_at is None or effective_at == ""))))

def calc_model_change_requests_lifecycle_change_by_unauthorized_agent(change_operation, approved_by_agent, steward_agent, authority_agent):
    """
    TRUE when a definition was created, modified or retired on the approval of someone who is neither steward nor authority.
    
    Formula: =AND(OR({{ChangeOperation}} = "CreateDefinition", {{ChangeOperation}} = "ModifyDefinition", {{ChangeOperation}} = "RetireDefinition"), {{ApprovedByAgent}} <> "", {{ApprovedByAgent}} <> {{StewardAgent}}, {{ApprovedByAgent}} <> {{AuthorityAgent}})
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_or(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'CreateDefinition')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'ModifyDefinition')), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(change_operation), 'RetireDefinition')))), _erb.erb_bool3((not (approved_by_agent is None or approved_by_agent == ""))), _erb.erb_bool3(_erb.erb_ne(_erb.erb_nullif(approved_by_agent), steward_agent)), _erb.erb_bool3(_erb.erb_ne(_erb.erb_nullif(approved_by_agent), authority_agent)))

def calc_model_change_requests_would_make_instances_inconsistent(assessed_inconsistent_count):
    """
    TRUE when the assessment found existing instance data the change would make inconsistent.
    
    Formula: ={{AssessedInconsistentCount}} > 0
    """
    return _erb.erb_cmp(assessed_inconsistent_count, '>', 0)

def calc_model_change_requests_would_alter_inferences(assessed_inference_count):
    """
    TRUE when the assessment found inferences the change would alter.
    
    Formula: ={{AssessedInferenceCount}} > 0
    """
    return _erb.erb_cmp(assessed_inference_count, '>', 0)

def calc_model_change_requests_would_alter_query_results(assessed_query_result_count):
    """
    TRUE when the assessment found query results the change would alter.
    
    Formula: ={{AssessedQueryResultCount}} > 0
    """
    return _erb.erb_cmp(assessed_query_result_count, '>', 0)

