def calc_competency_question_set_entries_is_outgrown_baseline_question(is_original_baseline, days_since_added, relevance_verdict):
    """
    TRUE for an original question that after more than a year of operation no longer fits what the organization needs.
    
    Formula: =AND({{IsOriginalBaseline}}, {{DaysSinceAdded}} > 365, {{RelevanceVerdict}} = "NoLongerRelevant")
    """
    return _erb.erb_and((is_original_baseline is True), _erb.erb_bool3(_erb.erb_cmp(days_since_added, '>', 365)), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(relevance_verdict), 'NoLongerRelevant')))

