# =============================================================================
# KNOWLEDGEAUDITITEMS
# One knowledge area an audit assessed: the level needed, the level the client holds, and any provider that holds it.
# =============================================================================

# Level 1

def calc_knowledge_audit_items_name(knowledge_audit, knowledge_area):
    """
    Display name.
    
    Formula: ={{KnowledgeAudit}} & " / " & {{KnowledgeArea}}
    """
    return (_erb.erb_text(knowledge_audit) + ' / ' + _erb.erb_text(knowledge_area))

def calc_knowledge_audit_items_has_internal_shortfall(held_internal_level, needed_level):
    """
    TRUE when the client holds less than it needs.
    
    Formula: ={{HeldInternalLevel}} < {{NeededLevel}}
    """
    return _erb.erb_cmp(_erb.erb_nullif(held_internal_level), '<', _erb.erb_nullif(needed_level))

def calc_knowledge_audit_items_is_single_team_silo(held_internal_level, needed_level, internal_holding_team_count):
    """
    TRUE when knowledge the client does hold sits with exactly one internal team.
    
    Formula: =AND({{HeldInternalLevel}} >= {{NeededLevel}}, {{InternalHoldingTeamCount}} = 1)
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_cmp(_erb.erb_nullif(held_internal_level), '>=', _erb.erb_nullif(needed_level))), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(internal_holding_team_count), 1)))

# Level 2

def calc_knowledge_audit_items_is_knowledge_dependency(has_internal_shortfall, provider_holding_knowledge, provider_held_level, needed_level):
    """
    TRUE when the client falls short and relies on a provider that holds the knowledge at the needed level.
    
    Formula: =AND({{HasInternalShortfall}}, {{ProviderHoldingKnowledge}} <> "", {{ProviderHeldLevel}} >= {{NeededLevel}})
    """
    return _erb.erb_and(_erb.erb_bool3(has_internal_shortfall), _erb.erb_bool3((not (provider_holding_knowledge is None or provider_holding_knowledge == ""))), _erb.erb_bool3(_erb.erb_cmp(_erb.erb_nullif(provider_held_level), '>=', _erb.erb_nullif(needed_level))))

def calc_knowledge_audit_items_is_unnamed_finding(has_internal_shortfall, named_knowledge_gap):
    """
    TRUE when an audit found a gap or dependency and nobody recorded it as a named knowledge gap.
    
    Formula: =AND({{HasInternalShortfall}}, {{NamedKnowledgeGap}} = "")
    """
    return _erb.erb_and(_erb.erb_bool3(has_internal_shortfall), _erb.erb_bool3((named_knowledge_gap is None or named_knowledge_gap == "")))

# Level 3

def calc_knowledge_audit_items_is_coverage_gap(has_internal_shortfall, is_knowledge_dependency):
    """
    TRUE when the client falls short and no provider available to it holds the knowledge either.
    
    Formula: =AND({{HasInternalShortfall}}, NOT({{IsKnowledgeDependency}}))
    """
    return _erb.erb_and(_erb.erb_bool3(has_internal_shortfall), _erb.erb_bool3(_erb.erb_not(_erb.erb_bool3(is_knowledge_dependency))))


def compute_knowledge_audit_items_fields(record: dict) -> dict:
    """
    Compute all calculated fields for KnowledgeAuditItems.
    
    One knowledge area an audit assessed: the level needed, the level the client holds, and any provider that holds it.
    """
    result = dict(record)

    # Level 1 calculations
    try:
        result['name'] = calc_knowledge_audit_items_name(result.get('knowledge_audit'), result.get('knowledge_area'))
    except Exception as _field_exc:
        result['name'] = None
        result.setdefault('_erb_errors', {})['name'] = str(_field_exc)
    try:
        result['has_internal_shortfall'] = calc_knowledge_audit_items_has_internal_shortfall(result.get('held_internal_level'), result.get('needed_level'))
    except Exception as _field_exc:
        result['has_internal_shortfall'] = None
        result.setdefault('_erb_errors', {})['has_internal_shortfall'] = str(_field_exc)
    try:
        result['is_single_team_silo'] = calc_knowledge_audit_items_is_single_team_silo(result.get('held_internal_level'), result.get('needed_level'), result.get('internal_holding_team_count'))
    except Exception as _field_exc:
        result['is_single_team_silo'] = None
        result.setdefault('_erb_errors', {})['is_single_team_silo'] = str(_field_exc)

    # Level 2 calculations
    try:
        result['is_knowledge_dependency'] = calc_knowledge_audit_items_is_knowledge_dependency(result.get('has_internal_shortfall'), result.get('provider_holding_knowledge'), result.get('provider_held_level'), result.get('needed_level'))
    except Exception as _field_exc:
        result['is_knowledge_dependency'] = None
        result.setdefault('_erb_errors', {})['is_knowledge_dependency'] = str(_field_exc)
    try:
        result['is_unnamed_finding'] = calc_knowledge_audit_items_is_unnamed_finding(result.get('has_internal_shortfall'), result.get('named_knowledge_gap'))
    except Exception as _field_exc:
        result['is_unnamed_finding'] = None
        result.setdefault('_erb_errors', {})['is_unnamed_finding'] = str(_field_exc)

    # Level 3 calculations
    try:
        result['is_coverage_gap'] = calc_knowledge_audit_items_is_coverage_gap(result.get('has_internal_shortfall'), result.get('is_knowledge_dependency'))
    except Exception as _field_exc:
        result['is_coverage_gap'] = None
        result.setdefault('_erb_errors', {})['is_coverage_gap'] = str(_field_exc)

    # Convert empty strings to None for string fields
    for key in ['name']:
        if result.get(key) == '':
            result[key] = None

    return result

