# Level 1

def calc_role_assignment_update_tasks_name(role, trigger_event, trigger_occurred_at):
    """
    Display name.
    
    Formula: ={{Role}} & " " & {{TriggerEvent}} & " @ " & {{TriggerOccurredAt}}
    """
    return (_erb.erb_text(role) + ' ' + _erb.erb_text(trigger_event) + ' @ ' + _erb.erb_datetime_text(trigger_occurred_at))

def calc_role_assignment_update_tasks_lacks_named_trigger_owner(policy_trigger_owner_role, trigger_owner_cover_count):
    """
    TRUE when governance names no role responsible for triggering the update, or names one nobody holds.
    
    Formula: =OR({{PolicyTriggerOwnerRole}} = "", {{TriggerOwnerCoverCount}} = 0)
    """
    return _erb.erb_or(_erb.erb_bool3((policy_trigger_owner_role is None or policy_trigger_owner_role == "")), _erb.erb_bool3(_erb.erb_eq(trigger_owner_cover_count, 0)))

def calc_role_assignment_update_tasks_elapsed_minutes(completed_at, as_of_instant, trigger_occurred_at):
    """
    Minutes from the trigger to completion, or to the evaluation instant while incomplete.
    
    Formula: =IF({{CompletedAt}} = "", DATETIME_DIFF({{AsOfInstant}}, {{TriggerOccurredAt}}, "minutes"), DATETIME_DIFF({{CompletedAt}}, {{TriggerOccurredAt}}, "minutes"))
    """
    return (_erb.erb_datetime_diff(as_of_instant, trigger_occurred_at, 'minutes') if _erb.erb_bool3((completed_at is None or completed_at == "")) else _erb.erb_datetime_diff(completed_at, trigger_occurred_at, 'minutes'))

def calc_role_assignment_update_tasks_changed_role_instead_of_assignment(replacement_assignment, replacement_role, ending_role):
    """
    TRUE when a change of who does the work was made by moving it to a different role, so the steps bound to the old role had to be re-pointed.
    
    Formula: =AND({{ReplacementAssignment}} <> "", {{ReplacementRole}} <> {{EndingRole}})
    """
    return _erb.erb_and(_erb.erb_bool3((not (replacement_assignment is None or replacement_assignment == ""))), _erb.erb_bool3(_erb.erb_ne(replacement_role, ending_role)))

def calc_role_assignment_update_tasks_missed_next_dependent_run(dependent_run_role_step_count, dependent_run_started_at, trigger_occurred_at, completed_at):
    """
    TRUE when a run that needs the role started after the trigger and before the assignment change was recorded.
    
    Formula: =AND({{DependentRunRoleStepCount}} > 0, {{DependentRunStartedAt}} > {{TriggerOccurredAt}}, OR({{CompletedAt}} = "", {{CompletedAt}} > {{DependentRunStartedAt}}))
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_cmp(dependent_run_role_step_count, '>', 0)), _erb.erb_bool3(_erb.erb_cmp(dependent_run_started_at, '>', _erb.erb_nullif(trigger_occurred_at))), _erb.erb_bool3(_erb.erb_or(_erb.erb_bool3((completed_at is None or completed_at == "")), _erb.erb_bool3(_erb.erb_cmp(_erb.erb_nullif(completed_at), '>', dependent_run_started_at)))))

# Level 2

def calc_role_assignment_update_tasks_exceeded_update_sla(policy_sla_hours, elapsed_minutes):
    """
    TRUE when no service level is defined, or the update took longer than it allows.
    
    Formula: =OR({{PolicySlaHours}} = 0, {{ElapsedMinutes}} > ({{PolicySlaHours}} * 60))
    """
    return _erb.erb_or(_erb.erb_bool3(_erb.erb_eq(policy_sla_hours, 0)), _erb.erb_bool3(_erb.erb_cmp(elapsed_minutes, '>', _erb.erb_mul(policy_sla_hours, 60))))

def calc_role_assignment_update_tasks_stale_assignment_broke_routing(missed_next_dependent_run, failed_notice_count):
    """
    TRUE when the assignment was still stale at a run that needed it and that run's notice for the role reached the wrong person or nobody.
    
    Formula: =AND({{MissedNextDependentRun}}, {{FailedNoticeCount}} > 0)
    """
    return _erb.erb_and(_erb.erb_bool3(missed_next_dependent_run), _erb.erb_bool3(_erb.erb_cmp(failed_notice_count, '>', 0)))


