# =============================================================================
# KNOWLEDGETRACES
# One trace from a piece of organized knowledge (a process model, an activity definition or a constraint) to the collected material it rests on, with the role the material plays (origin, validation, extension, contradiction), how the knowledge was derived, and who confirmed it.
# =============================================================================

# Level 1

def calc_knowledge_traces_name(target_kind, source_material, trace_role):
    """
    Display name.
    
    Formula: ={{TargetKind}} & " <- " & {{SourceMaterial}} & " (" & {{TraceRole}} & ")" 
    """
    return (_erb.erb_text(target_kind) + ' <- ' + _erb.erb_text(source_material) + ' (' + _erb.erb_text(trace_role) + ')')

def calc_knowledge_traces_is_source_changed_since_taken(source_revised_at, source_collected_at):
    """
    TRUE when the source document was revised after the knowledge was taken from it.
    
    Formula: =AND({{SourceRevisedAt}} <> "", {{SourceRevisedAt}} > {{SourceCollectedAt}})
    """
    return _erb.erb_and(_erb.erb_bool3((not (source_revised_at is None or source_revised_at == ""))), _erb.erb_bool3(_erb.erb_cmp(source_revised_at, '>', source_collected_at)))

def calc_knowledge_traces_is_unfaithful_to_source(step, source_stated_duration_minutes, modeled_duration_minutes):
    """
    TRUE when the modeled step's duration differs from the duration its source states.
    
    Formula: =AND({{Step}} <> "", {{SourceStatedDurationMinutes}} > 0, {{ModeledDurationMinutes}} <> {{SourceStatedDurationMinutes}})
    """
    return _erb.erb_and(_erb.erb_bool3((not (step is None or step == ""))), _erb.erb_bool3(_erb.erb_cmp(_erb.erb_nullif(source_stated_duration_minutes), '>', 0)), _erb.erb_bool3(_erb.erb_ne(modeled_duration_minutes, _erb.erb_nullif(source_stated_duration_minutes))))

def calc_knowledge_traces_is_machine_derived(derived_by_agent, derived_by_agent_kind):
    """
    TRUE when a software or AI agent derived the knowledge from its source.
    
    Formula: =AND({{DerivedByAgent}} <> "", {{DerivedByAgentKind}} <> "Human")
    """
    return _erb.erb_and(_erb.erb_bool3((not (derived_by_agent is None or derived_by_agent == ""))), _erb.erb_bool3(_erb.erb_ne(derived_by_agent_kind, 'Human')))

def calc_knowledge_traces_is_self_validated(validated_by_agent, derived_by_agent):
    """
    TRUE when the agent who derived the knowledge is the one who confirmed it.
    
    Formula: =AND({{ValidatedByAgent}} <> "", {{ValidatedByAgent}} = {{DerivedByAgent}})
    """
    return _erb.erb_and(_erb.erb_bool3((not (validated_by_agent is None or validated_by_agent == ""))), _erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(validated_by_agent), _erb.erb_nullif(derived_by_agent))))

def calc_knowledge_traces_has_incomplete_provenance(source_material, derivation_route, validated_by_agent):
    """
    TRUE when the origin, the derivation route or the confirmation is missing.
    
    Formula: =OR({{SourceMaterial}} = "", {{DerivationRoute}} = "", {{ValidatedByAgent}} = "")
    """
    return _erb.erb_or(_erb.erb_bool3((source_material is None or source_material == "")), _erb.erb_bool3((derivation_route is None or derivation_route == "")), _erb.erb_bool3((validated_by_agent is None or validated_by_agent == "")))

def calc_knowledge_traces_provenance_statement(source_material, derivation_route, derived_by_agent, validated_by_agent):
    """
    Origin, route and confirmation in one line.
    
    Formula: ="From " & {{SourceMaterial}} & "; route: " & {{DerivationRoute}} & "; derived by " & {{DerivedByAgent}} & "; confirmed by " & {{ValidatedByAgent}}
    """
    return ('From ' + _erb.erb_text(source_material) + '; route: ' + _erb.erb_text(derivation_route) + '; derived by ' + _erb.erb_text(derived_by_agent) + '; confirmed by ' + _erb.erb_text(validated_by_agent))

def calc_knowledge_traces_is_aspect_unsupported_by_source_kind(traced_aspect, source_material_kind):
    """
    TRUE when a workaround is cited to something other than observation notes, or actual execution to something other than an event trace.
    
    Formula: =OR(AND({{TracedAspect}} = "Workaround", {{SourceMaterialKind}} <> "FieldNotes"), AND({{TracedAspect}} = "ActualExecution", {{SourceMaterialKind}} <> "MinedEventTrace"))
    """
    return _erb.erb_or(_erb.erb_bool3(_erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(traced_aspect), 'Workaround')), _erb.erb_bool3(_erb.erb_ne(source_material_kind, 'FieldNotes')))), _erb.erb_bool3(_erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(traced_aspect), 'ActualExecution')), _erb.erb_bool3(_erb.erb_ne(source_material_kind, 'MinedEventTrace')))))

def calc_knowledge_traces_is_document_origin(trace_role, source_is_document):
    """
    TRUE when the knowledge was first taken from a document.
    
    Formula: =AND({{TraceRole}} = "Origin", {{SourceIsDocument}})
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(trace_role), 'Origin')), _erb.erb_bool3(source_is_document))

def calc_knowledge_traces_is_document_trailing_practice(trace_role, contradicted_document, source_is_practice_evidence, source_collected_at, contradicted_document_revised_at):
    """
    TRUE when practice evidence collected after the document's last revision contradicts it.
    
    Formula: =AND({{TraceRole}} = "Contradicts", {{ContradictedDocument}} <> "", {{SourceIsPracticeEvidence}}, {{SourceCollectedAt}} > {{ContradictedDocumentRevisedAt}})
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(trace_role), 'Contradicts')), _erb.erb_bool3((not (contradicted_document is None or contradicted_document == ""))), _erb.erb_bool3(source_is_practice_evidence), _erb.erb_bool3(_erb.erb_cmp(source_collected_at, '>', contradicted_document_revised_at)))

def calc_knowledge_traces_prescribed_versus_enacted(contradicted_document, source_material, source_statement):
    """
    For a contradiction: what the document prescribes against what practice evidence shows.
    
    Formula: =IF({{ContradictedDocument}} = "", "", "Prescribed in " & {{ContradictedDocument}} & "; enacted per " & {{SourceMaterial}} & ": " & {{SourceStatement}})
    """
    return ('' if _erb.erb_bool3((contradicted_document is None or contradicted_document == "")) else ('Prescribed in ' + _erb.erb_text(contradicted_document) + '; enacted per ' + _erb.erb_text(source_material) + ': ' + _erb.erb_text(source_statement)))

# Level 2

def calc_knowledge_traces_is_document_start_never_validated(is_document_origin, step, step_elicited_validation_count):
    """
    TRUE when a step taken from a document has never been confirmed by capture from people.
    
    Formula: =AND({{IsDocumentOrigin}}, {{Step}} <> "", {{StepElicitedValidationCount}} = 0)
    """
    return _erb.erb_and(_erb.erb_bool3(is_document_origin), _erb.erb_bool3((not (step is None or step == ""))), _erb.erb_bool3(_erb.erb_eq(step_elicited_validation_count, 0)))

def calc_knowledge_traces_is_document_start_never_extended(is_document_origin, step, step_elicited_extension_count):
    """
    TRUE when a step taken from a document has never been extended by capture from people.
    
    Formula: =AND({{IsDocumentOrigin}}, {{Step}} <> "", {{StepElicitedExtensionCount}} = 0)
    """
    return _erb.erb_and(_erb.erb_bool3(is_document_origin), _erb.erb_bool3((not (step is None or step == ""))), _erb.erb_bool3(_erb.erb_eq(step_elicited_extension_count, 0)))


def compute_knowledge_traces_fields(record: dict) -> dict:
    """
    Compute all calculated fields for KnowledgeTraces.
    
    One trace from a piece of organized knowledge (a process model, an activity definition or a constraint) to the collected material it rests on, with the role the material plays (origin, validation, extension, contradiction), how the knowledge was derived, and who confirmed it.
    """
    result = dict(record)

    # Level 1 calculations
    try:
        result['name'] = calc_knowledge_traces_name(result.get('target_kind'), result.get('source_material'), result.get('trace_role'))
    except Exception as _field_exc:
        result['name'] = None
        result.setdefault('_erb_errors', {})['name'] = str(_field_exc)
    try:
        result['is_source_changed_since_taken'] = calc_knowledge_traces_is_source_changed_since_taken(result.get('source_revised_at'), result.get('source_collected_at'))
    except Exception as _field_exc:
        result['is_source_changed_since_taken'] = None
        result.setdefault('_erb_errors', {})['is_source_changed_since_taken'] = str(_field_exc)
    try:
        result['is_unfaithful_to_source'] = calc_knowledge_traces_is_unfaithful_to_source(result.get('step'), result.get('source_stated_duration_minutes'), result.get('modeled_duration_minutes'))
    except Exception as _field_exc:
        result['is_unfaithful_to_source'] = None
        result.setdefault('_erb_errors', {})['is_unfaithful_to_source'] = str(_field_exc)
    try:
        result['is_machine_derived'] = calc_knowledge_traces_is_machine_derived(result.get('derived_by_agent'), result.get('derived_by_agent_kind'))
    except Exception as _field_exc:
        result['is_machine_derived'] = None
        result.setdefault('_erb_errors', {})['is_machine_derived'] = str(_field_exc)
    try:
        result['is_self_validated'] = calc_knowledge_traces_is_self_validated(result.get('validated_by_agent'), result.get('derived_by_agent'))
    except Exception as _field_exc:
        result['is_self_validated'] = None
        result.setdefault('_erb_errors', {})['is_self_validated'] = str(_field_exc)
    try:
        result['has_incomplete_provenance'] = calc_knowledge_traces_has_incomplete_provenance(result.get('source_material'), result.get('derivation_route'), result.get('validated_by_agent'))
    except Exception as _field_exc:
        result['has_incomplete_provenance'] = None
        result.setdefault('_erb_errors', {})['has_incomplete_provenance'] = str(_field_exc)
    try:
        result['provenance_statement'] = calc_knowledge_traces_provenance_statement(result.get('source_material'), result.get('derivation_route'), result.get('derived_by_agent'), result.get('validated_by_agent'))
    except Exception as _field_exc:
        result['provenance_statement'] = None
        result.setdefault('_erb_errors', {})['provenance_statement'] = str(_field_exc)
    try:
        result['is_aspect_unsupported_by_source_kind'] = calc_knowledge_traces_is_aspect_unsupported_by_source_kind(result.get('traced_aspect'), result.get('source_material_kind'))
    except Exception as _field_exc:
        result['is_aspect_unsupported_by_source_kind'] = None
        result.setdefault('_erb_errors', {})['is_aspect_unsupported_by_source_kind'] = str(_field_exc)
    try:
        result['is_document_origin'] = calc_knowledge_traces_is_document_origin(result.get('trace_role'), result.get('source_is_document'))
    except Exception as _field_exc:
        result['is_document_origin'] = None
        result.setdefault('_erb_errors', {})['is_document_origin'] = str(_field_exc)
    try:
        result['is_document_trailing_practice'] = calc_knowledge_traces_is_document_trailing_practice(result.get('trace_role'), result.get('contradicted_document'), result.get('source_is_practice_evidence'), result.get('source_collected_at'), result.get('contradicted_document_revised_at'))
    except Exception as _field_exc:
        result['is_document_trailing_practice'] = None
        result.setdefault('_erb_errors', {})['is_document_trailing_practice'] = str(_field_exc)
    try:
        result['prescribed_versus_enacted'] = calc_knowledge_traces_prescribed_versus_enacted(result.get('contradicted_document'), result.get('source_material'), result.get('source_statement'))
    except Exception as _field_exc:
        result['prescribed_versus_enacted'] = None
        result.setdefault('_erb_errors', {})['prescribed_versus_enacted'] = str(_field_exc)

    # Level 2 calculations
    try:
        result['is_document_start_never_validated'] = calc_knowledge_traces_is_document_start_never_validated(result.get('is_document_origin'), result.get('step'), result.get('step_elicited_validation_count'))
    except Exception as _field_exc:
        result['is_document_start_never_validated'] = None
        result.setdefault('_erb_errors', {})['is_document_start_never_validated'] = str(_field_exc)
    try:
        result['is_document_start_never_extended'] = calc_knowledge_traces_is_document_start_never_extended(result.get('is_document_origin'), result.get('step'), result.get('step_elicited_extension_count'))
    except Exception as _field_exc:
        result['is_document_start_never_extended'] = None
        result.setdefault('_erb_errors', {})['is_document_start_never_extended'] = str(_field_exc)

    # Convert empty strings to None for string fields
    for key in ['name', 'provenance_statement', 'prescribed_versus_enacted']:
        if result.get(key) == '':
            result[key] = None

    return result

