# MINEDFLOWEDGES
# One step-to-step hand-off reconstructed from a system event log by a process-mining run: how many cases took it, how long cases waited before the next step, and whether it is kept as observed behavior or recorded as intended logic.
# =============================================================================

# Level 1

def calc_mined_flow_edges_name(from_step, to_step):
    """
    Display name.
    
    Formula: ={{FromStep}} & " -> " & {{ToStep}}
    """
    return (_erb.erb_text(from_step) + ' -> ' + _erb.erb_text(to_step))

def calc_mined_flow_edges_is_undocumented_path(documented_transition_count):
    """
    TRUE when cases took a hand-off the documented model does not contain.
    
    Formula: ={{DocumentedTransitionCount}} = 0
    """
    return _erb.erb_eq(documented_transition_count, 0)

def calc_mined_flow_edges_is_bottleneck(to_step_expected_minutes, median_wait_minutes):
    """
    TRUE when cases wait more than four times the entered step's documented duration.
    
    Formula: =AND({{ToStepExpectedMinutes}} > 0, {{MedianWaitMinutes}} > 4 * {{ToStepExpectedMinutes}})
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_cmp(to_step_expected_minutes, '>', 0)), _erb.erb_bool3(_erb.erb_cmp(_erb.erb_nullif(median_wait_minutes), '>', _erb.erb_mul(4, to_step_expected_minutes))))

def calc_mined_flow_edges_is_mined_path_recorded_as_intent_without_decision(recorded_stance, intent_decision_by):
    """
    TRUE when a mined hand-off is recorded as intended logic and nobody decided it should be.
    
    Formula: =AND({{RecordedStance}} = "Intended", {{IntentDecisionBy}} = "")
    """
    return _erb.erb_and(_erb.erb_bool3(_erb.erb_eq(_erb.erb_nullif(recorded_stance), 'Intended')), _erb.erb_bool3((intent_decision_by is None or intent_decision_by == "")))


def compute_mined_flow_edges_fields(record: dict) -> dict:
    """
    Compute all calculated fields for MinedFlowEdges.
    
    One step-to-step hand-off reconstructed from a system event log by a process-mining run: how many cases took it, how long cases waited before the next step, and whether it is kept as observed behavior or recorded as intended logic.
    """
    result = dict(record)

    # Level 1 calculations
    try:
        result['name'] = calc_mined_flow_edges_name(result.get('from_step'), result.get('to_step'))
    except Exception as _field_exc:
        result['name'] = None
        result.setdefault('_erb_errors', {})['name'] = str(_field_exc)
    try:
        result['is_undocumented_path'] = calc_mined_flow_edges_is_undocumented_path(result.get('documented_transition_count'))
    except Exception as _field_exc:
        result['is_undocumented_path'] = None
        result.setdefault('_erb_errors', {})['is_undocumented_path'] = str(_field_exc)
    try:
        result['is_bottleneck'] = calc_mined_flow_edges_is_bottleneck(result.get('to_step_expected_minutes'), result.get('median_wait_minutes'))
    except Exception as _field_exc:
        result['is_bottleneck'] = None
        result.setdefault('_erb_errors', {})['is_bottleneck'] = str(_field_exc)
    try:
        result['is_mined_path_recorded_as_intent_without_decision'] = calc_mined_flow_edges_is_mined_path_recorded_as_intent_without_decision(result.get('recorded_stance'), result.get('intent_decision_by'))
    except Exception as _field_exc:
        result['is_mined_path_recorded_as_intent_without_decision'] = None
        result.setdefault('_erb_errors', {})['is_mined_path_recorded_as_intent_without_decision'] = str(_field_exc)

    # Convert empty strings to None for string fields
    for key in ['name']:
        if result.get(key) == '':
            result[key] = None

    return result

