# =============================================================================
# ARTIFACTHANDOFFS
# One artifact passing from the step that produces it to a step that consumes it, asserted per declared input variable. The edge table the upgrade blast radius is traversed over.
# =============================================================================

# Level 1

def calc_artifact_handoffs_name(from_step, to_step):
    """
    Display name.
    
    Formula: ={{FromStep}} & " -> " & {{ToStep}}
    """
    return (_erb.erb_text(from_step) + ' -> ' + _erb.erb_text(to_step))

def calc_artifact_handoffs_disagrees_with_declared_variable(from_step, declared_source_step, to_step, declared_consumer_step):
    """
    TRUE when a recorded hand-off names different steps than the input variable it feeds declares, so traversal and declaration have drifted apart.
    
    Formula: =OR({{FromStep}} <> {{DeclaredSourceStep}}, {{ToStep}} <> {{DeclaredConsumerStep}})
    """
    return _erb.erb_or(_erb.erb_bool3(_erb.erb_ne(_erb.erb_nullif(from_step), declared_source_step)), _erb.erb_bool3(_erb.erb_ne(_erb.erb_nullif(to_step), declared_consumer_step)))


def compute_artifact_handoffs_fields(record: dict) -> dict:
    """
    Compute all calculated fields for ArtifactHandoffs.
    
    One artifact passing from the step that produces it to a step that consumes it, asserted per declared input variable. The edge table the upgrade blast radius is traversed over.
    """
    result = dict(record)

    # Level 1 calculations
    try:
        result['name'] = calc_artifact_handoffs_name(result.get('from_step'), result.get('to_step'))
    except Exception as _field_exc:
        result['name'] = None
        result.setdefault('_erb_errors', {})['name'] = str(_field_exc)
    try:
        result['disagrees_with_declared_variable'] = calc_artifact_handoffs_disagrees_with_declared_variable(result.get('from_step'), result.get('declared_source_step'), result.get('to_step'), result.get('declared_consumer_step'))
    except Exception as _field_exc:
        result['disagrees_with_declared_variable'] = None
        result.setdefault('_erb_errors', {})['disagrees_with_declared_variable'] = str(_field_exc)

    # Convert empty strings to None for string fields
    for key in ['name']:
        if result.get(key) == '':
            result[key] = None

    return result


# =============================================================================
# DISPATCHER
# =============================================================================

def compute_all_calculated_fields(record: dict, entity_name: str) -> dict:
    """Compute every calculated field of one record of the named entity
    (PascalCase or snake_case). Lookups and aggregations read other rows,
    so they are computed by erb_run over the whole dataset, not here."""
    compute = _ERB_COMPUTE_BY_NAME.get(entity_name)
    if compute is None:
        raise KeyError(
            f"compute_all_calculated_fields called with unknown entity {entity_name!r}. "
            f"Known entities: {sorted(_ERB_COMPUTE_BY_NAME)!r}.")
    return compute(record)


